CREATE TABLE IF NOT EXISTS plugins (id VARCHAR(255) PRIMARY KEY, "name" VARCHAR(255) NOT NULL, description TEXT NOT NULL, "version" VARCHAR(255) NOT NULL, manifest_version VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS plugin_instances (id uuid PRIMARY KEY, endpoint TEXT NOT NULL, status VARCHAR(255) NOT NULL, plugin_id VARCHAR(255) NOT NULL, last_heartbeat_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT fk_plugin_instances_plugin_id__id FOREIGN KEY (plugin_id) REFERENCES plugins(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS plugin_capabilities (id VARCHAR(255), plugin_id VARCHAR(255), description TEXT NOT NULL, CONSTRAINT pk_plugin_capabilities PRIMARY KEY (plugin_id, id), CONSTRAINT fk_plugin_capabilities_plugin_id__id FOREIGN KEY (plugin_id) REFERENCES plugins(id) ON DELETE CASCADE ON UPDATE RESTRICT);
